    -- Dialog and button strings (WoWPro_Frames.lua).
    ["Resize guide window"] = "Ridimensiona la finestra della guida",
    ["Okay"] = "OK",
    ["Cancel"] = "Annulla",
    ["Skipping the step |cFFFFFF00%s|r will also cause the following steps to skip:\n|cFFFFFF00%s|r\nIf you wanted to just complete the step, |cffff0000cancel|r this dialog and right-click instead.\n"] = "Saltare il passaggio |cFFFFFF00%s|r comporterà il salto anche dei passaggi seguenti:\n|cFFFFFF00%s|r\nSe volevi solo completare il passaggio, |cffff0000annulla|r questa finestra e fai invece clic con il pulsante destro.\n",
    ["Discord Server!"] = "Server Discord!",
    ["Connect with other players, get help, and stay updated!"] = "Connettiti con altri giocatori, ottieni aiuto e resta aggiornato!",
    ["Copy"] = "Copia",
    ["Close"] = "Chiudi",
    ["Load Next Guide"] = "Carica la guida successiva",
    ["Choose Guide From List"] = "Scegli la guida dall'elenco",
    -- Configuration section headers (WoWPro_Config.lua).
    ["Behavior"] = "Comportamento",
    ["Button Display Options"] = "Opzioni visualizzazione pulsanti",
    ["Window Layout"] = "Layout finestra",
    ["Position & Anchor"] = "Posizione e ancoraggio",
    ["Window Sizing"] = "Dimensioni finestra",
    ["Content Spacing"] = "Spaziatura contenuti",
    ["Appearance"] = "Aspetto",
    ["Guide Behavior"] = "Comportamento guida",
    ["About"] = "Informazioni",
    ["What WoW-Pro Does"] = "Cosa fa WoW-Pro",
    ["Where To Start"] = "Da dove iniziare",
    ["Runtime Status"] = "Stato di esecuzione",
    ["Stay Connected"] = "Resta connesso",
    ["Discord Invite"] = "Invito Discord",
    ["Source Repository"] = "Repository del codice",
    ["Help"] = "Aiuto",
    ["Getting Started"] = "Per iniziare",
    ["Starting WoW-Pro"] = "Avviare WoW-Pro",
    ["Exporting And Sharing"] = "Esportare e condividere",
    ["Default is 0.5 seconds."] = "Il valore predefinito è 0,5 secondi.",
    -- About tab, command list, and help paragraphs (WoWPro_Config.lua).
    ["WoW-Pro is a community-built addon collection that helps with questing, leveling, and guide-driven progression."] = "WoW-Pro è una raccolta di addon creata dalla community che aiuta con missioni, livellamento e progressione guidata.",
    ["It has grown through years of player contributions, covering content from legacy expansions through current Retail."] = "È cresciuta negli anni grazie ai contributi dei giocatori, coprendo contenuti dalle espansioni passate al Retail attuale.",
    ["New here: begin with Main and Guide Display to set automation, layout, and text style."] = "Nuovo qui? Inizia da Generale e Visualizzazione guida per impostare automazione, layout e stile del testo.",
    ["Troubleshooting: open Main > Tools for logging and About > Commands for command shortcuts."] = "Risoluzione dei problemi: apri Generale > Strumenti per i registri e Informazioni > Comandi per le scorciatoie dei comandi.",
    ["Use these links for announcements, support, and development updates."] = "Usa questi link per annunci, supporto e aggiornamenti sullo sviluppo.",
    ["Tip: Include your guide name or ID and a short log snippet when asking for help in Discord."] = "Suggerimento: includi il nome o l'ID della guida e un breve estratto del registro quando chiedi aiuto su Discord.",
    ["Use /wp or /wow-pro with the following commands:"] = "Usa /wp o /wow-pro con i seguenti comandi:",
    ["- where: print current map position and area details"] = "- where: mostra la posizione attuale sulla mappa e i dettagli dell'area",
    ["- reset: clear WoW-Pro saved runtime state"] = "- reset: cancella lo stato di esecuzione salvato di WoW-Pro",
    ["- clear-log / log: clear or show the debug log"] = "- clear-log / log: cancella o mostra il registro di debug",
    ["- guide-bug / trade-bug: create focused bug reports"] = "- guide-bug / trade-bug: crea segnalazioni di bug mirate",
    ["- devcoords / devzone / devmode: developer mapping helpers"] = "- devcoords / devzone / devmode: strumenti di mappatura per sviluppatori",
    ["- flightids [dest]: inspect flight node IDs for your current map"] = "- flightids [dest]: ispeziona gli ID dei nodi di volo della mappa attuale",
    -- Getting Started and Troubleshooting bullets (WoWPro_Config.lua).
    ["Start here to select a guide and set your questing preferences."] = "Inizia qui: scegli una guida e imposta le tue preferenze per le missioni.",
    ["- If steps do not advance, check Main > General automation and the Ranks page. Open Main > Tools to enable debugging and inspect the log."] = "- Se i passaggi non avanzano, controlla l'automazione in Generale > Generale e la pagina Gradi. Apri Generale > Strumenti per attivare il debug e controllare il registro.",
    ["- Use /wp log to inspect debug entries and /wp clear-log before reproducing issues."] = "- Usa /wp log per esaminare le voci di debug e /wp clear-log prima di riprodurre il problema.",
    ["- Use /wp reset if saved state becomes inconsistent after major patches."] = "- Usa /wp reset se lo stato salvato diventa incoerente dopo aggiornamenti importanti.",
    ["- If needed, share logs and guide ID in Discord for faster support."] = "- Se necessario, condividi i registri e l'ID della guida su Discord per ottenere assistenza più rapida.",
    -- Rank, automation, and legend help text (WoWPro_Config.lua).
    ["Ranks control how many optional steps are included in guides.\n1 = shortest route (core progression only), 2 = balanced route, 3 = fullest route (most optional content).\n\nPriority for this character is: Toon Rank first, then Global Rank as fallback."] = "I gradi controllano quanti passaggi facoltativi sono inclusi nelle guide.\n1 = percorso più breve (solo progressione principale), 2 = percorso equilibrato, 3 = percorso più completo (la maggior parte dei contenuti facoltativi).\n\nPriorità per questo personaggio: prima il grado del personaggio, poi il grado globale come riserva.",
    ["Default rank for all characters and guides unless overridden.\n\nUse 1 for speed leveling, 2 for normal play, or 3 for completion-focused runs."] = "Grado predefinito per tutti i personaggi e le guide, salvo sostituzione.\n\nUsa 1 per livellare velocemente, 2 per il gioco normale o 3 per partite orientate al completamento.",
    ["Character-specific override for this toon.\n\nIf set, this value is used instead of Global Rank for this character."] = "Sostituzione specifica per questo personaggio.\n\nSe impostato, questo valore viene usato al posto del grado globale per questo personaggio.",
    ["Profile-level rank for this module's guide type.\n\nUse this when you want different strictness for %s than your default rank."] = "Grado a livello di profilo per il tipo di guida di questo modulo.\n\nUsalo quando vuoi un rigore diverso per %s rispetto al tuo grado predefinito.",
    ["Adjust the delay used while waiting for WoW API state updates. Increase this if steps complete too early; decrease it if updates feel sluggish."] = "Regola l'attesa durante l'aggiornamento dello stato dell'API di WoW. Aumentala se i passaggi si completano troppo presto; riducila se gli aggiornamenti sono lenti.",
    ["Action letters appear in each step and indicate what kind of step it is. Use this legend to quickly decode guide rows."] = "Le lettere di azione compaiono in ogni passaggio e indicano che tipo di passaggio è. Usa questa legenda per decifrare rapidamente le righe della guida.",
    -- Getting Started walkthrough steps (WoWPro_Config.lua).
    ["1) Click the Horn icon for the classic Guide List, or right-click the Options icon for the new Guide List. Choose a guide matching your level, campaign, or expansion."] = "1) Fai clic sull'icona del corno per l'elenco delle guide classico, oppure fai clic con il pulsante destro sull'icona delle opzioni per il nuovo elenco. Scegli una guida adatta al tuo livello, campagna o espansione.",
    ["2) Open Main > General for Auto Select, Auto Accept, Auto Turn-in, Quest Tracking, and Auto-Load Guide. Use Main > Guide Modifiers to choose optional content."] = "2) Apri Generale > Generale per selezione automatica, accettazione automatica, consegna automatica, monitoraggio missioni e caricamento automatico. Usa Generale > Modificatori guida per scegliere i contenuti facoltativi.",
    ["3) Open Guide Display > Window Layout to adjust Position & Anchor, Window Sizing, and Content Spacing. Use Appearance for backgrounds and Text Formatting for fonts and text size."] = "3) Apri Visualizzazione guida > Layout finestra per regolare Posizione e ancoraggio, Dimensioni finestra e Spaziatura contenuti. Usa Aspetto per gli sfondi e Formattazione del testo per caratteri e dimensioni.",
    ["4) Start playing. WoW-Pro will load the selected guide into the main frame and advance steps as quests and objectives update."] = "4) Inizia a giocare. WoW-Pro carica la guida selezionata nella finestra principale e avanza i passaggi man mano che missioni e obiettivi si aggiornano.",
    ["5) If a guide looks stuck or out of sync, use /wp reset to clear guide state and /wp log to inspect the debug log before reporting the issue."] = "5) Se una guida sembra bloccata o non sincronizzata, usa /wp reset per cancellare lo stato della guida e /wp log per controllare il registro di debug prima di segnalare il problema.",
    -- Recorder walkthrough (WoWPro_Config.lua).
    ["Starting With The Recorder"] = "Iniziare con il registratore",
    ["1) Enable WoWPro_Recorder in the AddOns list, then reload the UI if needed. When it is active, a recorder toolbar appears above the main WoW-Pro frame."] = "1) Attiva WoWPro_Recorder nell'elenco degli addon, poi ricarica l'interfaccia se necessario. Quando è attivo, sopra la finestra principale di WoW-Pro compare una barra degli strumenti del registratore.",
    ["2) Click New on the recorder toolbar to create a guide. Choose the guide type first, then fill in the guide fields such as Guide ID, zone, author, faction, and level range."] = "2) Fai clic su Nuovo nella barra degli strumenti del registratore per creare una guida. Scegli prima il tipo di guida, poi compila i campi come ID guida, zona, autore, fazione e intervallo di livelli.",
    ["3) Finish the New Guide dialog to register the guide. WoW-Pro will load that guide immediately so you can begin editing or recording steps into it."] = "3) Completa la finestra Nuova guida per registrare la guida. WoW-Pro carica subito quella guida così puoi iniziare a modificarla o a registrare passaggi.",
    ["4) Click Record to capture questing progress while you play. Click Stop any time you want to pause before moving, testing, or editing steps manually."] = "4) Fai clic su Registra per acquisire l'avanzamento delle missioni mentre giochi. Fai clic su Interrompi in qualsiasi momento per mettere in pausa prima di spostarti, testare o modificare i passaggi manualmente.",
    ["5) Use Open to load an existing guide for editing. Use Save to write the current recorder version to your saved guides so it can be reopened later."] = "5) Usa Apri per caricare una guida esistente da modificare. Usa Salva per scrivere la versione attuale del registratore nelle guide salvate, così potrai riaprirla più tardi.",
    ["6) In Advanced mode, use Add to insert a step after the selected step, or use buttons such as Run, Flight, Portal, Note, and Delete to refine the route."] = "6) In modalità avanzata, usa Aggiungi per inserire un passaggio dopo quello selezionato, oppure pulsanti come Corri, Volo, Portale, Nota ed Elimina per rifinire il percorso.",
    ["7) Use /wpr to toggle Basic or Advanced recorder mode. Use /wpr help to list recorder slash commands, and /wpr qdebug on or off if you need extra quest API logging while testing."] = "7) Usa /wpr per passare dalla modalità registratore base a quella avanzata. Usa /wpr help per elencare i comandi slash del registratore e /wpr qdebug on o off se ti servono log aggiuntivi dell'API missioni durante i test.",
    ["8) After saving, reopen the guide with Open and run through a few steps to verify quest IDs, notes, and automatic completion behave the way you expect."] = "8) Dopo il salvataggio, riapri la guida con Apri e percorri alcuni passaggi per verificare che ID missione, note e completamento automatico funzionino come previsto.",
    -- Export and sharing steps (WoWPro_Config.lua).
    ["1) Click Save after recording or editing. The recorder opens a large text box containing the full Lua guide definition for the currently loaded guide."] = "1) Fai clic su Salva dopo aver registrato o modificato. Il registratore apre una grande casella di testo con la definizione Lua completa della guida attualmente caricata.",
    ["2) Copy that text and paste it into a guide file if you want to move the guide into the addon source, share it with another author, or submit it for review."] = "2) Copia quel testo e incollalo in un file di guida se vuoi spostare la guida nel codice sorgente dell'addon, condividerla con un altro autore o inviarla per la revisione.",
    ["3) The recorder also keeps a saved copy in WoWPro_RecorderDB, so you can reload the guide later with Open even if you have not moved it into a permanent guide file yet."] = "3) Il registratore conserva anche una copia in WoWPro_RecorderDB, così puoi ricaricare la guida più tardi con Apri anche se non l'hai ancora spostata in un file di guida permanente.",
    ["4) For out-of-game backup or sharing, look in your WoW SavedVariables for WoWPro_Recorder.lua under WTF/Account/<account>/SavedVariables. That file stores the recorder guides saved on this installation."] = "4) Per backup o condivisione fuori dal gioco, cerca WoWPro_Recorder.lua nelle tue SavedVariables di WoW, in WTF/Account/<account>/SavedVariables. Quel file contiene le guide del registratore salvate su questa installazione.",
    -- Broker popups (WoWPro_Broker.lua).
    ["Would you like to trash %s?"] = "Vuoi distruggere %s?",
    ["Please enter the quest ID to select and then click GO!"] = "Inserisci l'ID della missione da selezionare, poi fai clic su Vai!",
    ["Go!"] = "Vai!",
