    -- Recorder step-editor descriptions, part 1.
    ["Check if this is a chat step."] = "Seleziona se questo è un passaggio chat.",
    ["Check if this is a quest completion step NOT involving combat."] = "Seleziona se è un passaggio di completamento missione SENZA combattimento.",
    ["Check if this is an optional step."] = "Seleziona se è un passaggio facoltativo.",
    ["Check if this is an sticky step."] = "Seleziona se è un passaggio fissato.",
    ["Check if this is an unsticky step."] = "Seleziona se è un passaggio non fissato.",
    ["Choose the quest you'd like to base this step on:"] = "Scegli la missione su cui basare questo passaggio:",
    ["Are you sure you want to delete this step?\n"] = "Sei sicuro di voler eliminare questo passaggio?\n",
    ["Are you sure you want to delete this guide? This action cannot be undone.\n\n"] = "Sei sicuro di voler eliminare questa guida? Questa azione non può essere annullata.\n\n",
    ["The step's type."] = "Il tipo del passaggio.",
    ["The main text for this step - often the quest name."] = "Il testo principale di questo passaggio, spesso il nome della missione.",
    ["The main text for this step - often the quest title."] = "Il testo principale di questo passaggio, spesso il titolo della missione.",
    -- Recorder step-editor descriptions, part 2.
    ["Insert your current location and zone"] = "Inserisci la tua posizione e zona attuali",
    ["Jump to a step index while staying in the editor."] = "Salta all'indice di un passaggio senza uscire dall'editor.",
    ["Open a numbered list of every step in the current guide."] = "Apre un elenco numerato di tutti i passaggi della guida corrente.",
    ["Registers the guide to be used. Current guide will be lost unless saved."] = "Registra la guida per l'uso. La guida corrente andrà persa se non salvata.",
    ["The guide's type determines what kind of events will be listened for."] = "Il tipo di guida determina quali eventi vengono ascoltati.",
    ["The quest you choose will determine what values are loaded into the step editor."] = "La missione scelta determina quali valori vengono caricati nell'editor dei passaggi.",
    ["The rank of the step. If you are unsure, leave it as 1."] = "Il grado del passaggio. Se non sei sicuro, lascia 1.",
    ["This step will be marked complete when you reach this level."] = "Questo passaggio sarà segnato come completato quando raggiungi questo livello.",
    ["The quest tied to this step. If this quest is complete, this step will be checked off."] = "La missione collegata a questo passaggio. Se completata, il passaggio sarà spuntato.",
    ["You need a zone tag if the coordinates lead to a point outside the guide's title zone."] = "Serve un tag di zona se le coordinate portano a un punto fuori dalla zona del titolo della guida.",
    ["Makes a run step complete based on coordinates rather than zone name."] = "Fa completare un passaggio di corsa in base alle coordinate invece che al nome della zona.",
    ["Makes a run step complete based on coordinates rather than zone name. (CC)"] = "Fa completare un passaggio di corsa in base alle coordinate invece che al nome della zona. (CC)",
    ["Makes a run step complete based on a series of coordinates, followed in order."] = "Fa completare un passaggio di corsa in base a una serie di coordinate, seguite in ordine.",
    ["Makes a run step complete based on a series of coordinates, followed in order. (CS)"] = "Fa completare un passaggio di corsa in base a una serie di coordinate, seguite in ordine. (CS)",
    ["Do not complete based on coordinates. Just show the dots. (CN)"] = "Non completare in base alle coordinate. Mostra solo i punti. (CN)",
    -- Recorder step-editor descriptions, part 3.
    ["All guides are listed here, including those that come with the addon and those you have created using the recorder."] = "Tutte le guide sono elencate qui, incluse quelle fornite con l'addon e quelle create con il registratore.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please."] = "Dettagli su come completare questo passaggio della guida. Non più di una o due frasi, per favore.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please. Only leave blank for blatantly obvious steps."] = "Dettagli su come completare questo passaggio della guida. Non più di una o due frasi, per favore. Lascia vuoto solo per passaggi ovvi.",
    ["Displayed if the user has the profession at the required skill level. Please enter in the form of 'Profession SkillLevel'."] = "Visualizzato se l'utente ha la professione al livello richiesto. Inserisci nel formato 'Professione Livello'.",
    ["Enter coordinates for the step here, in the form '##.##,##.##'. Seperate multiple coordinates with semicolons (;)"] = "Inserisci qui le coordinate del passaggio, nel formato '##.##,##.##'. Separa più coordinate con punto e virgola (;).",
    ["Full emitted guide lines for the current guide. The selected step is prefixed with >>."] = "Righe di guida complete per la guida corrente. Il passaggio selezionato è preceduto da >>.",
    ["If a particular quest must be active, list it's QID here. Seperate multiple actives with AND/OR (&^)"] = "Se una missione specifica deve essere attiva, indica qui il suo QID. Separa più missioni attive con AND/OR (&^).",
    ["If it would be helpful to provide an easy way to target a named mob, enter the mob's name here. Use only for hard to find mobs."] = "Se sarebbe utile offrire un modo semplice per selezionare un nemico con nome, inserisci qui il suo nome. Usa solo per nemici difficili da trovare.",
    ["If the quest has a prerequisite, list it's QID here. Seperate multiple prerequisites with AND/OR (&^)"] = "Se la missione ha un prerequisito, indica qui il suo QID. Separa più prerequisiti con AND/OR (&^).",
    ["If the step compeltes when you loot a certain number of items, put the number here."] = "Se il passaggio si completa quando raccogli un certo numero di oggetti, inserisci il numero qui.",
    ["If the step completes based on a scenario stage or objective, put the stage (or stage and objective separated by a ;) here."] = "Se il passaggio si completa in base a una fase o obiettivo di scenario, inserisci qui la fase (o fase e obiettivo separati da ;).",
    ["If the step completes based on one or two quest objectives, not the whole quest, you can enter the quest objective here. Seperate multiple objectives with semicolons (;)"] = "Se il passaggio si completa in base a uno o due obiettivi di missione e non all'intera missione, puoi inserire qui l'obiettivo. Separa più obiettivi con punto e virgola (;).",
    ["If the step completes when you loot an item, put it's ID here."] = "Se il passaggio si completa quando raccogli un oggetto, inserisci qui il suo ID.",
    ["If the step requires you to use an item, put it's ID here."] = "Se il passaggio richiede di usare un oggetto, inserisci qui il suo ID.",
    ["If this quest is a Lead-In to another quest (meaning that other quest CAN be completed without this one, and doing so makes this quest no longer available), please list the quest it leads to's QID here."] = "Se questa missione è un'introduzione a un'altra (l'altra missione PUÒ essere completata senza questa, e così facendo questa non è più disponibile), indica qui il QID della missione a cui porta.",
    ["Would you like to automatically populate some fields of the step based on a quest from your log? You can edit it afterwards."] = "Vuoi compilare automaticamente alcuni campi del passaggio da una missione nel tuo registro? Puoi modificarli in seguito.",
